#include <stdio.h>
#include <stdlib.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 10000

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));
    link->size = 0;
    link->head = NULL;
    link->tail = NULL;
    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *listNode = (ListNode *) malloc(sizeof(ListNode));
    listNode->ele = ele;
    listNode->next = NULL;

    if(link->size == 0) {
        link->head = listNode;
        link->tail = listNode;
    } else {
        link->tail->next = listNode;
        link->tail = listNode;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList* link) {
    if(link->size == 0) exit(-1);

    ListNode* removed = link->head;

    if(link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}

int main() {
    int times[MAX_SIZE];
    int times_size = 0;

    while (scanf("%d", &times[times_size++])) {
        if(getchar() != ' ') break;
    }

    // 记录题解
    int ans = 0;

    // 根节点的索引是0
    LinkedList* queue = new_LinkedList();
    addLast_LinkedList(queue, 0);

    while (queue->size > 0) {
        int fa = removeFirst_LinkedList(queue); // 父节点索引

        int ch1 = 2 * fa + 1; // 左子节点索引
        int ch2 = 2 * fa + 2; // 右子节点索引

        // fa是否存在左子节点
        int ch1_exist = ch1 < times_size && times[ch1] != -1;
        // fa是否存在右子节点
        int ch2_exist = ch2 < times_size && times[ch2] != -1;

        // fa如果存在左子节点
        if(ch1_exist) {
            times[ch1] += times[fa];
            addLast_LinkedList(queue, ch1);
        }

        // fa如果存在右子节点
        if(ch2_exist) {
            times[ch2] += times[fa];
            addLast_LinkedList(queue, ch2);
        }

        // fa是叶子节点
        if(!ch1_exist && !ch2_exist) {
            // 保留叶子节点中最大时延
            ans = MAX(ans, times[fa]);
        }
    }

    printf("%d\n", ans);

    return 0;
}
